    CONSTRAINT personas_genero_check CHECK (((genero)::text = ANY (ARRAY[('Masculino'::character varying)::text, ('Femenino'::character varying)::text, ('No binario'::character varying)::text, ('Prefiero no reportar'::character varying)::text]))),
