--
-- Name: personas_con_edad; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.personas_con_edad AS
 SELECT p.id,
    p.numero_documento,
    p.tipo_documento,
    p.primer_nombre,
    p.segundo_nombre,
    p.apellidos,
    p.fecha_nacimiento,
    p.genero,
    p.correo_electronico,
    p.celular,
    p.foto_url,
    p.created_at,
    p.updated_at,
    p.created_by,
    p.updated_by,
    EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) AS edad,
        CASE
            WHEN (EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) < (18)::numeric) THEN 'Menor de edad'::text
            WHEN ((EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) >= (18)::numeric) AND (EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) <= (65)::numeric)) THEN 'Adulto'::text
            ELSE 'Adulto mayor'::text
        END AS grupo_edad
   FROM public.personas p;


